namespace Threadforge.Threadlink.Editor
{
    using System;
    using System.IO;
    using UnityEngine;
    using PackageInfo = UnityEditor.PackageManager.PackageInfo;

    /// <summary>Every Threadlink package of this release, generated by the release tooling into the workspace package.</summary>
    [Serializable]
    public sealed class HubCatalog
    {
        /// <summary>One package.</summary>
        [Serializable]
        public sealed class Entry
        {
            /// <summary>Package name.</summary>
            public string name;

            /// <summary>Name shown in the Package Manager.</summary>
            public string displayName;

            /// <summary>One-sentence description.</summary>
            public string description;

            /// <summary>Feature family used for grouping.</summary>
            public string family;

            /// <summary>Manual page.</summary>
            public string documentationUrl;

            /// <summary>Threadlink packages this package depends on.</summary>
            public string[] dependencies = Array.Empty<string>();

            /// <summary>Sample display names.</summary>
            public string[] samples = Array.Empty<string>();
        }

        /// <summary>Framework version every package of this release shares.</summary>
        public string version;

        /// <summary>The core package.</summary>
        public string framework;

        /// <summary>Catalog packages that the complete framework install leaves out (samples).</summary>
        public string[] framework_excludes = Array.Empty<string>();

        /// <summary>Scoped registry that serves the packages.</summary>
        public string registry;

        /// <summary>Registry scopes the packages and their dependencies need.</summary>
        public string[] scopes = Array.Empty<string>();

        /// <summary>All packages.</summary>
        public Entry[] packages = Array.Empty<Entry>();

        /// <summary>Loads the catalog shipped with the installed workspace package.</summary>
        public static HubCatalog Load()
        {
            var package = PackageInfo.FindForAssembly(typeof(HubCatalog).Assembly);
            string root = package != null ? package.resolvedPath : Path.GetFullPath("Packages/com.threadforge.threadlink");
            string path = Path.Combine(root, "Editor", "Workspace", "Hub", "catalog.json");
            if (!File.Exists(path))
                throw new FileNotFoundException("The Threadlink package has no Hub catalog.", path);
            return Parse(File.ReadAllText(path));
        }

        /// <summary>Parses catalog JSON.</summary>
        public static HubCatalog Parse(string json) =>
            JsonUtility.FromJson<HubCatalog>(json) ?? throw new InvalidDataException("The Hub catalog is empty.");
    }
}
